INSERT INTO `modx_site_htmlsnippets` VALUES (1,0,0,'fiDefaultEmailTpl','The default chunk used for the email. Please do not edit this chunk, as this will be overwritten when updating FormIt.',0,5,0,'<p>[[+fields]]</p>',0,'a:0:{}',0,''),(2,0,0,'fiDefaultFiarTpl','The default chunk used for the autoresponder email. Please do not edit this chunk, as this will be overwritten when updating FormIt.',0,5,0,'<p>Hello [[+name]],</p>\n\n<p>Your message has been received. We will respond as soon as possible. Thank you for contacting us.</p>\n\n<p>NOTE: This is an automatic response; please do not respond to this message directly.</p>\n\n<p>Here is your message:<br />\n[[+message:nl2br]]</p>',0,'a:0:{}',0,''),(3,0,0,'fiDefaultOptGroupTpl','The default chunk used by the FormItCountryOptions snippet for the select optgroup. Please do not edit this chunk, as this will be overwritten when updating FormIt.',0,5,0,'<optgroup label=\"[[+text]]\">\n    [[+options]]\n</optgroup>',0,'a:0:{}',0,''),(4,0,0,'fiDefaultOptionTpl','The default chunk used by the FormItCountryOptions snippet for the select option. Please do not edit this chunk, as this will be overwritten when updating FormIt.',0,5,0,'<option value=\"[[+value]]\"[[+selected]]>[[+text]]</option>',0,'a:0:{}',0,''),(5,1,0,'tpl.FetchIt.example','',0,6,0,'<form action=\"[[~[[*id]]]]\" method=\"post\">\r\n  <fieldset>\r\n\r\n    <div>\r\n      <label>[[%fetchit_label_name]]\r\n        <input type=\"text\" name=\"name\" value=\"[[+fi.name]]\"/>\r\n        <span data-error=\"name\">[[+fi.error.name]]</span>\r\n      </label>\r\n    </div>\r\n\r\n    <div>\r\n      <label>[[%fetchit_label_email]]\r\n        <input type=\"text\" name=\"email\" value=\"[[+fi.email]]\"/>\r\n        <span data-error=\"email\">[[+fi.error.email]]</span>\r\n      </label>\r\n    </div>\r\n\r\n    <div>\r\n      <label>[[%fetchit_label_message]]\r\n        <textarea name=\"message\" rows=\"5\">[[+fi.message]]</textarea>\r\n        <span data-error=\"message\">[[+fi.error.message]]</span>\r\n      </label>\r\n    </div>\r\n\r\n    <div>\r\n      <button type=\"reset\">[[%fetchit_reset]]</button>\r\n      <button type=\"submit\">[[%fetchit_submit]]</button>\r\n    </div>\r\n\r\n    [[+fi.success:is=`1`:then=`\r\n    <div role=\"alert\">[[+fi.successMessage]]</div>\r\n    `]]\r\n    [[+fi.validation_error:is=`1`:then=`\r\n    <div role=\"alert\">[[+fi.validation_error_message]]</div>\r\n    `]]\r\n  </fieldset>\r\n</form>',0,NULL,0,'core/components/fetchit/elements/chunks/example.tpl');
/*!40000 ALTER TABLE `modx_site_htmlsnippets` ENABLE KEYS */;
UNLOCK TABLES;

