n * Automatically generates and outputs a U.S. state list for usage in forms\n *\n * @var modX $modx\n * @var array $scriptProperties\n *\n * @package formit\n */\nuse Sterc\\FormIt;\n\n$fi = new FormIt($modx, $scriptProperties);\n\n/** @var fiStateOptions $so */\n$so = $fi->loadModule(\'fiStateOptions\', \'stateOptions\', $scriptProperties);\n$so->initialize();\n$so->getData();\n$so->iterate();\n\nreturn $so->output();',0,'a:6:{s:8:\"selected\";a:7:{s:4:\"name\";s:8:\"selected\";s:4:\"desc\";s:23:\"prop_fiso.selected_desc\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:17:\"formit:properties\";s:4:\"area\";s:0:\"\";}s:3:\"tpl\";a:7:{s:4:\"name\";s:3:\"tpl\";s:4:\"desc\";s:18:\"prop_fiso.tpl_desc\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:18:\"fiDefaultOptionTpl\";s:7:\"lexicon\";s:17:\"formit:properties\";s:4:\"area\";s:0:\"\";}s:7:\"useAbbr\";a:7:{s:4:\"name\";s:7:\"useAbbr\";s:4:\"desc\";s:22:\"prop_fiso.useabbr_desc\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:1;s:7:\"lexicon\";s:17:\"formit:properties\";s:4:\"area\";s:0:\"\";}s:17:\"selectedAttribute\";a:7:{s:4:\"name\";s:17:\"selectedAttribute\";s:4:\"desc\";s:32:\"prop_fiso.selectedattribute_desc\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:20:\" selected=\"selected\"\";s:7:\"lexicon\";s:17:\"formit:properties\";s:4:\"area\";s:0:\"\";}s:13:\"toPlaceholder\";a:7:{s:4:\"name\";s:13:\"toPlaceholder\";s:4:\"desc\";s:28:\"prop_fiso.toplaceholder_desc\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:0:\"\";s:7:\"lexicon\";s:17:\"formit:properties\";s:4:\"area\";s:0:\"\";}s:7:\"country\";a:7:{s:4:\"name\";s:7:\"country\";s:4:\"desc\";s:22:\"prop_fiso.country_desc\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:16:\"[[++cultureKey]]\";s:7:\"lexicon\";s:17:\"formit:properties\";s:4:\"area\";s:0:\"\";}}','',0,''),(39,0,0,'FormItLoadSavedForm','Prehook to load previously saved form.',0,5,0,'use Sterc\\FormIt\\Model\\FormItForm;\n\n/**\n * A custom FormIt prehook for fetching saved form data. - Based on FormItSaveForm\n *\n * @var modX $modx\n * @var array $scriptProperties\n * @var FormIt $formit\n * @var fiHooks $hook\n *\n * @package formit\n */\n/* setup default properties */\n// If prehook fails do we continue?\n$return          = $modx->getOption(\'returnValueOnFail\', $formit->config, true);\n$formEncrypt     = $modx->getOption(\'formEncrypt\', $formit->config, false);\n$formFields      = $modx->getOption(\'formFields\', $formit->config, false);\n$fieldNames      = $modx->getOption(\'fieldNames\', $formit->config, false);\n$updateSavedForm = $modx->getOption(\'updateSavedForm\', $formit->config, false); // true, false, \'1\', \'0\', or \'values\'\n\n// If FormIt config says don\'t update, don\'t do it\nif (!$updateSavedForm) {\n    return $return;\n}\n\n// In order to load form values, the user must provide the hash key somehow\n// Usually with a $_GET parameter, but a property in $formit->config will override.\n$formHashKeyField = $modx->getOption(\'savedFormHashKeyField\', $formit->config, \'savedFormHashKey\');\n$formHashKey      = \'\';\nif (isset($_GET[$formHashKeyField])) {\n    $formHashKey = (string) $_GET[$formHashKeyField];\n}\n\nif ($hook->getValue($formHashKeyField)) {\n    $formHashKey = (string) $hook->getValue($formHashKeyField);\n}\n\nif (isset($formit->config[$formHashKeyField])) {\n    $formHashKey = $formit->config[$formHashKeyField];\n}\n\n// our hashing methods return 32 chars. if no valid hash key we\'re done here.\nif (strlen($formHashKey) !== 32) {\n    return $return;\n}\n\n// Try to fetch the saved form\n$savedForm = $modx->getObject(FormItForm::class, [\'hash\' => $formHashKey]);\nif (!$savedForm) {\n    return $return;\n}\n\nif ($formFields) {\n    $formFields = explode(\',\', $formFields);\n    foreach($formFields as $k => $v) {\n        $formFields[$k] = trim($v);\n    }\n}\n\n// Initialize the data array\n// Handle encryption\nif ($formEncrypt) {\n    $encrypted_data = $savedForm->get(\'values\');\n    $data           = $savedForm->decrypt($encrypted_data);\n} else {\n    $data = $savedForm->get(\'values\');\n}\n\nif (is_string($data)) {\n    $data = $modx->fromJSON($data);\n}\n\nif (!is_array($data)) {\n    return $return;\n}\n\n//Change the fieldnames\nif ($fieldNames) {\n    $newDataArray   = [];\n    $fieldLabels    = [];\n    $formFieldNames = explode(\',\', $fieldNames);\n    foreach($formFieldNames as $formFieldName){\n        list($name, $label) = explode(\'==\', $formFieldName);\n        // reverse order from FormItSaveForm snippet\n        $fieldLabels[trim($label)] = trim($name);\n    }\n\n    foreach ($data as $key => $value) {\n        if ($fieldLabels[$key]) {\n            $newDataArray[$fieldLabels[$key]] = $value;\n        } else {\n            $newDataArray[$key] = $value;\n        }\n    }\n\n    $data = $newDataArray;\n}\n\n// Always pass back in the provided hash key\n$data[$formHashKeyField] = $formHashKey;\n\n$hook->setValues($data);\n\nreturn true;',0,'a:0:{}','',0,''),(40,1,0,'FetchIt','',0,6,0,'use FetchIt\\FetchIt;\r\n\r\n/** @var modX $modx */\r\n/** @var FetchIt $FetchIt */\r\n/** @var array $scriptProperties */\r\n\r\nrequire_once MODX_CORE_PATH . \'components/fetchit/src/FetchIt.php\';\r\n$FetchIt = new FetchIt($modx, $scriptProperties);\r\n\r\n$snippet = $modx->getOption(\'snippet\', $scriptProperties, \'FormIt\', true);\r\n$tpl = $modx->getOption(\'form\', $scriptProperties, \'tpl.FetchIt.example\', true);\r\n\r\n/** @var pdoTools $pdo */\r\nif ($pdo =\r\n    $modx->services->has(\'pdoTools\') ?\r\n    $modx->services->get(\'pdoTools\') :\r\n    false\r\n) {\r\n    $content = $pdo->getChunk($tpl, $scriptProperties);\r\n} else {\r\n    $content = $modx->getChunk($tpl, $scriptProperties);\r\n}\r\nif (empty($content)) {\r\n    return $modx->lexicon(\'fetchit_err_chunk_nf\', array(\'name\' => $tpl));\r\n}\r\n\r\n// Add method = post\r\nif (preg_match(\'#<form.*?method=(?:\"|\\\')(.*?)(?:\"|\\\')#i\', $content)) {\r\n    $content = preg_replace(\'#<form(.*?)method=(?:\"|\\\')(.*?)(?:\"|\\\')#i\', \'<form\\\\1method=\"post\"\', $content);\r\n} else {\r\n    $content = str_ireplace(\'<form\', \'<form method=\"post\"\', $content);\r\n}\r\n\r\n// Add action for form processing\r\n$action = md5(http_build_query($scriptProperties));\r\n// Add selector to tag form\r\nif (preg_match(\'#<form.*?data-fetchit=(?:\"|\\\')(.*?)(?:\"|\\\')#i\', $content, $matches)) {\r\n    $content = preg_replace(\'#<form(.*?)data-fetchit=(?:\"|\\\')(.*?)(?:\"|\\\')#i\', \'<form\\\\data-fetchit=\"$action\"\', $content);\r\n} else {\r\n    $content = str_ireplace(\'<form\', \'<form data-fetchit=\"\' . $action . \'\"\', $content);\r\n}\r\n\r\n$FetchIt->loadScript($action);\r\n\r\n// Save snippet properties\r\nif (!empty(session_id())) {\r\n    // ... to user`s session\r\n    $_SESSION[\'FetchIt\'][$action] = $scriptProperties;\r\n} else {\r\n    // ... to cache file\r\n    $modx->cacheManager->set(\'fetchit/props_\' . $action, $scriptProperties, 3600);\r\n}\r\n\r\n// Call snippet for preparation of form\r\n$action = !empty($_SERVER[\'HTTP_X_FETCHIT_ACTION\'])\r\n    ? $_SERVER[\'HTTP_X_FETCHIT_ACTION\']\r\n    : $action;\r\n\r\n$FetchIt->process($action, $_REQUEST);\r\n\r\n// Return chunk\r\nreturn $content;',0,'a:4:{s:4:\"form\";a:7:{s:4:\"name\";s:4:\"form\";s:4:\"desc\";s:17:\"fetchit_prop_form\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:19:\"tpl.FetchIt.example\";s:7:\"lexicon\";s:18:\"fetchit:properties\";s:4:\"area\";s:0:\"\";}s:7:\"snippet\";a:7:{s:4:\"name\";s:7:\"snippet\";s:4:\"desc\";s:20:\"fetchit_prop_snippet\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:6:\"FormIt\";s:7:\"lexicon\";s:18:\"fetchit:properties\";s:4:\"area\";s:0:\"\";}s:9:\"actionUrl\";a:7:{s:4:\"name\";s:9:\"actionUrl\";s:4:\"desc\";s:22:\"fetchit_prop_actionUrl\";s:4:\"type\";s:9:\"textfield\";s:7:\"options\";a:0:{}s:5:\"value\";s:24:\"[[+assetsUrl]]action.php\";s:7:\"lexicon\";s:18:\"fetchit:properties\";s:4:\"area\";s:0:\"\";}s:20:\"clearFieldsOnSuccess\";a:7:{s:4:\"name\";s:20:\"clearFieldsOnSuccess\";s:4:\"desc\";s:33:\"fetchit_prop_clearFieldsOnSuccess\";s:4:\"type\";s:13:\"combo-boolean\";s:7:\"options\";a:0:{}s:5:\"value\";b:1;s:7:\"lexicon\";s:18:\"fetchit:properties\";s:4:\"area\";s:0:\"\";}}','',0,'core/components/fetchit/elements/snippets/fetchit.php');
