INSERT INTO `modx_site_templates` VALUES (1,0,0,'BaseTemplate','',0,0,'',0,'<!doctype html>\r\n<html lang=\"en\">\r\n<head>\r\n    <title>[[*pagetitle]] - [[++site_name]]</title>\r\n    <base href=\"[[!++site_url]]\">\r\n    <meta charset=\"[[++modx_charset]]\">\r\n    <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1\">\r\n\r\n    <style>\r\n        body {\r\n            background-color: #eee;\r\n            font-family: sans-serif;\r\n            font-size: 20px;\r\n            line-height: 1.4em;\r\n            padding: 0;\r\n            margin: 0;\r\n        }\r\n        body.loaded {\r\n            font-family: \'Open Sans\', sans-serif;\r\n        }\r\n        .container {\r\n            display: block;\r\n            max-width: 960px;\r\n            margin: 2em auto 2em;\r\n            padding: 2em;\r\n            background: #fff;\r\n            border: 1px solid #ddd;\r\n            border-radius: 3px;\r\n        }\r\n        .container > section {\r\n            height: 100%;\r\n            width: 60%;\r\n            display: inline-block;\r\n            float: left;\r\n            margin-bottom: 2em;\r\n        }\r\n        .container > aside {\r\n            height: 100%;\r\n            display: inline-block;\r\n            width: 30%;\r\n            border-left: 2px dashed #eee;\r\n            float: right;\r\n            padding-left: 1.5em;\r\n        }\r\n        .logo {\r\n            background: url(\'[[++manager_url]]templates/default/images/modx-logo-color.svg\') no-repeat center transparent;\r\n            width: 220px;\r\n            height: 85px;\r\n            background-size: contain;\r\n            display: block;\r\n            position: relative;\r\n            text-indent: -9999px;\r\n            margin: 2em auto;\r\n        }\r\n        h1, h2, h3, h4, h5 {\r\n            color: #494949;\r\n            font-family: \'Open Sans\', sans-serif;\r\n            font-weight: 700;\r\n        }\r\n        h1 {\r\n            font-size: 36px;\r\n            color: #137899;\r\n        }\r\n        h2 {\r\n            font-size: 29px;\r\n        }\r\n        h3 {\r\n            font-size: 24px;\r\n        }\r\n        a {\r\n            color: #0f7096;\r\n        }\r\n        ul {\r\n            padding-left: 2em;\r\n        }\r\n        img {\r\n            max-width: 100%;\r\n        }\r\n        .cta-button {\r\n            display: block;\r\n            text-align: center;\r\n            vertical-align: middle;\r\n            -webkit-transform: translateZ(0);\r\n            transform: translateZ(0);\r\n            box-shadow: 0 0 1px rgba(0, 0, 0, 0);\r\n            -webkit-backface-visibility: hidden;\r\n            backface-visibility: hidden;\r\n            -moz-osx-font-smoothing: grayscale;\r\n            position: relative;\r\n            overflow: hidden;\r\n            margin: .2em 0;\r\n            padding: 1em;\r\n            cursor: pointer;\r\n            background: #67a749;\r\n            text-decoration: none;\r\n            border-radius: 3px;\r\n            color: #fff;\r\n            -webkit-tap-highlight-color: rgba(0,0,0,0);\r\n        }\r\n        .cta-button:before {\r\n            content: \"\";\r\n            position: absolute;\r\n            z-index: -1;\r\n            left: 50%;\r\n            right: 50%;\r\n            bottom: 0;\r\n            background: #137899;\r\n            height: 5px;\r\n            -webkit-transition-property: left, right;\r\n            transition-property: left, right;\r\n            -webkit-transition-duration: 0.3s;\r\n            transition-duration: 0.3s;\r\n            -webkit-transition-timing-function: ease-out;\r\n            transition-timing-function: ease-out;\r\n        }\r\n        .cta-button:hover:before, .cta-button:focus:before, .cta-button:active:before {\r\n            left: 0;\r\n            right: 0;\r\n        }\r\n        .companies {\r\n            clear: both;\r\n            display: block;\r\n            width: 100%;\r\n            padding: 1em 0 0;\r\n            border-top: 2px dashed #eee;\r\n        }\r\n        .companies h3 {\r\n            text-align: center;\r\n            margin: 0;\r\n        }\r\n        .companies ul {\r\n            margin: 0;\r\n            padding: 0;\r\n            list-style: none;\r\n            text-align: center;\r\n        }\r\n        .companies ul li {\r\n            display: inline-block;\r\n            padding: 0 1em;\r\n        }\r\n        .companies ul li:first-child {\r\n            padding-left: 0;\r\n        }\r\n        .companies ul li:last-child {\r\n            padding-right: 0;\r\n        }\r\n        .companies ul li a {\r\n            display: block;\r\n            position: relative;\r\n            text-indent: -99999px;\r\n            width: 200px;\r\n            height: 75px;\r\n            background-repeat: no-repeat;\r\n            background-size: 200px;\r\n            background-position: center;\r\n        }\r\n        .companies ul li.modmore a {\r\n            background-image: url(data:image/png;base64,);\r\n        }\r\n        .companies ul li.extrasio a {\r\n            background-image: url(data:image/png;base64,);\r\n        }\r\n        .companies ul li.modstore a {\r\n            background-image: url(data:image/jpeg;base64,);\r\n        }\r\n        .companies ul li.modxextras a {\r\n            background-image: url(data:image/svg+xml;base64,);\r\n        }\r\n        .disclaimer {\r\n            max-width: 960px;\r\n            display: block;\r\n            margin: 0 auto;\r\n            text-align: center;\r\n            color: #333;\r\n            font-size: .6em;\r\n        }\r\n        @media (min-width: 768px) and (max-width: 991px)  {\r\n            .container {\r\n                padding: 1em;\r\n                border: 0;\r\n                border-radius: 0;\r\n            }\r\n        }\r\n        @media (max-width: 767px)  {\r\n            body {\r\n                font-size: 16px;\r\n            }\r\n            .container {\r\n                padding: 1em;\r\n                margin: 0 0 1em;\r\n                border: 0;\r\n                border-radius: 0;\r\n            }\r\n            .container > section, .container > aside {\r\n                float: none;\r\n                width: 100%;\r\n            }\r\n            .container aside {\r\n                border: 0;\r\n                padding: 0;\r\n            }\r\n            .logo {\r\n                width: 100%;\r\n                height: 48px;\r\n            }\r\n            h1 {\r\n                font-size: 24px;\r\n            }\r\n            h2 {\r\n                font-size: 19px;\r\n            }\r\n            h3 {\r\n                font-size: 16px;\r\n            }\r\n            .companys ul li {\r\n                display: block;\r\n            }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n<a href=\"https://modx.com\" title=\"MODX\" class=\"logo\" target=\"_blank\">MODX</a>\r\n<div class=\"container\">\r\n    <section>\r\n        <h1>[[*longtitle:default=`[[*pagetitle]]`]]</h1>\r\n        [[*content]]\r\n    </section>\r\n    <aside>\r\n        <a href=\"[[++manager_url]]\" title=\"Your MODX manager\" class=\"cta-button\">Go to the&nbsp;manager</a>\r\n        <h3>Learn more about&nbsp;MODX</h3>\r\n        <ul>\r\n            <li><a href=\"https://docs.modx.com/3.x/en/index\" target=\"_blank\">Official&nbsp;Documentation</a></li>\r\n            <li><a href=\"https://docs.modx.com/3.x/en/getting-started/friendly-urls\" target=\"_blank\">Using Friendly&nbsp;URLs</a></li>\r\n            <li><a href=\"https://docs.modx.com/current/en/building-sites/extras\" target=\"_blank\">Package&nbsp;Management</a></li>\r\n            <li><a href=\"https://modx.com/blog/\" target=\"_blank\">Official MODX&nbsp;Blog</a></li>\r\n            <li><a href=\"http://www.discovermodx.com/\" target=\"_blank\">Discover&nbsp;MODX</a></li>\r\n            <li><a href=\"https://modx.today\" target=\"_blank\">MODX.today</a></li>\r\n        </ul>\r\n        <h3>Get help!</h3>\r\n        <ul>\r\n            <li><a href=\"https://community.modx.com\" target=\"_blank\">Official MODX&nbsp;Forums</a></li>\r\n            <li><a href=\"https://modx.org/\" target=\"_blank\">MODX on&nbsp;Slack</a></li>\r\n            <li><a href=\"https://twitter.com/modx\" target=\"_blank\">MODX on&nbsp;Twitter</a></li>\r\n            <li><a href=\"https://www.facebook.com/modxcms\" target=\"_blank\">MODX on&nbsp;Facebook</a></li>\r\n            <li><a href=\"https://modx.com/professionals/\" target=\"_blank\">Find a MODX&nbsp;Professional</a></li>\r\n        </ul>\r\n    </aside>\r\n    <div class=\"companies\">\r\n        <h3>Extend MODX with&nbsp;Extras</h3>\r\n        <ul>\r\n            <li class=\"modxextras\"><a href=\"https://modx.com/extras/\" title=\"MODX extras\" target=\"_blank\">MODX&nbsp;extras</a></li>\r\n            <li class=\"modmore\"><a href=\"https://www.modmore.com/extras/\" title=\"modmore.com\" target=\"_blank\">modmore.com</a></li>\r\n            <li class=\"modstore\"><a href=\"https://modstore.pro/\" title=\"modstore.pro\" target=\"_blank\">modstore.pro</a></li>\r\n            <li class=\"extrasio\"><a href=\"https://extras.io/extras/\" title=\"Extras.io\" target=\"_blank\">Extras.io</a></li>\r\n        </ul>\r\n    </div>\r\n</div>\r\n<footer class=\"disclaimer\">\r\n    <p>&copy; 2005-present the <a href=\"https://modx.com\" target=\"_blank\">MODX</a> Content Management Framework (CMF) project. All rights reserved. MODX is licensed under the GNU&nbsp;GPL.</p>\r\n</footer>\r\n\r\n<script>\r\n    // Load the Open Sans font\r\n    try {\r\n        document.addEventListener(\"DOMContentLoaded\", function() { // prevent a Flash Of Unstyled Text (FOUT)\r\n            document.querySelector(\'head\').innerHTML += \"<link href=\'https://fonts.googleapis.com/css?family=Open+Sans:400,700\' rel=\'stylesheet\' type=\'text/css\'>\";\r\n            document.body.classList.add(\'loaded\');\r\n        });\r\n    } catch (e) { }\r\n\r\n    // Shuffle the vendors to prevent favoritism of one vendor over the other\r\n    // with thanks to http://james.padolsey.com/javascript/shuffling-the-dom/\r\n    function shuffle(elems) {\r\n        var allElems = (function(){\r\n            var ret = [], l = elems.length;\r\n            while (l--) {\r\n                if (elems[l].className !== \'modxextras\') {\r\n                    ret[ret.length] = elems[l];\r\n                }\r\n            }\r\n            return ret;\r\n        })();\r\n\r\n        var shuffled = (function(){\r\n            var l = allElems.length, ret = [];\r\n            while (l--) {\r\n                var random = Math.floor(Math.random() * allElems.length),\r\n                        randEl = allElems[random].cloneNode(true);\r\n                allElems.splice(random, 1);\r\n                ret[ret.length] = randEl;\r\n            }\r\n            return ret;\r\n        })(), l = elems.length;\r\n\r\n        // To make sure the MODX logo stays #1, we lower the count by one here (shuffling 3 instead of 4 items)\r\n        // and refer to elems[l+1] in the loop below. This matches because allElems was also filtered to not include\r\n        // the official MODX logo.\r\n        l--;\r\n        while (l--) {\r\n            elems[l+1].parentNode.insertBefore(shuffled[l], elems[l+1].nextSibling);\r\n            elems[l+1].parentNode.removeChild(elems[l+1]);\r\n        }\r\n    }\r\n    shuffle(document.querySelectorAll(\'.companies li\'));\r\n</script>\r\n\r\n</body>\r\n</html>\r\n',0,NULL,0,'','');
/*!40000 ALTER TABLE `modx_site_templates` ENABLE KEYS */;
UNLOCK TABLES;

